     1	/**
     2	 * Credential login, registration and password reset. No third-party provider.
     3	 *
     4	 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
     5	 *
     6	 * Note: `TaskflowEventMap` has no authentication event and the type is part of
     7	 * the frozen contract, so the declared `emit` is not reachable from here.
     8	 * Registration still publishes `member.joined` — through
     9	 * `OrganizationService.createOrganization`, which owns that membership row.
    10	 */
    11	import {
    12	  hashPassword,
    13	  hashToken,
    14	  randomToken,
    15	  verifyPassword,
    16	} from "@/lib/hash";
    17	import { consumeRateLimit } from "@/lib/rate-limit";
    18	import { slugify } from "@/lib/slug";
    19	import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
    20	import * as sessionRepo from "@/server/repositories/session-repository";
    21	import * as userRepo from "@/server/repositories/user-repository";
    22	import { toIsoTimestamp } from "@/types/common";
    23	import { createOrganization } from "./organization-service";
    24	import { renderEmail, sendEmail } from "./email-service";
    25	import { createSessionToken } from "./session-service";
    26	import type {
    27	  LoginInput,
    28	  PasswordResetConfirmInput,
    29	  PasswordResetRequestInput,
    30	  RegisterInput,
    31	} from "@/schemas/auth";
    32	import type { OrgId, SessionId } from "@/types/common";
    33	import type { User } from "@/types/member";
    34	import type { Organization } from "@/types/organization";
    35	
    36	/** Buckets guarding the unauthenticated endpoints. */
    37	const LOGIN_BUCKET = "auth:login";
    38	const RESET_BUCKET = "auth:password-reset";
    39	
    40	/**
    41	 * Rate limiting before a session exists has no tenant to charge against, so
    42	 * every unauthenticated attempt is billed to this sentinel bucket.
    43	 */
    44	const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;
    45	
    46	/** How long a password-reset link stays usable. */
    47	const RESET_TTL_MS = 60 * 60 * 1000;
    48	
    49	/**
    50	 * Registration creates the user and their first workspace in one step — a
    51	 * Taskflow account with no organization cannot do anything, so there is no
    52	 * intermediate state where one exists without the other.
    53	 */
    54	export async function register(
    55	  input: RegisterInput,
    56	): Promise<{ user: User; org: Organization }> {
    57	  const existing = await userRepo.findUserByEmail(input.email);
    58	  if (existing) {
    59	    throw new Error("An account with that email already exists");
    60	  }
    61	
    62	  const user = await userRepo.insertUser({
    63	    email: input.email,
    64	    name: input.name,
    65	    passwordHash: await hashPassword(input.password),
    66	  });
    67	
    68	  // A reserved or awkward name is handled downstream: `createOrganization`
    69	  // runs the slug through `uniqueSlug()`, which skips reserved words and
    70	  // suffixes collisions.
    71	  const org = await createOrganization(user.id, {
    72	    name: `${input.name}'s workspace`,
    73	    slug: slugify(input.name) || "workspace",
    74	    plan: "free",
    75	  });
    76	
    77	  const welcome = await renderEmail("welcome", {
    78	    orgName: org.name,
    79	    recipientName: user.name,
    80	  });
    81	  await sendEmail({ to: user.email, ...welcome });
    82	
    83	  return { user, org };
    84	}
    85	
    86	/**
    87	 * Credential login. The rate limit is charged before the password is checked,
    88	 * so a brute-force run is throttled whether or not it guesses correctly, and
    89	 * both failure modes return the same message.
    90	 */
    91	export async function login(
    92	  input: LoginInput,
    93	): Promise<{ user: User; token: string }> {
    94	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
    95	  if (!verdict.allowed) {
    96	    throw new Error("Too many sign-in attempts; try again shortly");
    97	  }
    98	
    99	  const user = await userRepo.findUserByEmail(input.email);
   100	  if (!user) throw new Error("Those credentials did not match");
   101	
   102	  const storedHash = await userRepo.findPasswordHash(user.id);
   103	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
   104	    throw new Error("Those credentials did not match");
   105	  }
   106	
   107	  const { token } = await createSessionToken(user.id);
   108	
   109	  return { user, token };
   110	}
   111	
   112	export async function logout(sessionId: SessionId): Promise<void> {
   113	  await sessionRepo.revokeSession(sessionId);
   114	}
   115	
   116	/**
   117	 * Always resolves, whether or not the address is known — telling an anonymous
   118	 * caller which emails have accounts is an enumeration oracle. Only the token's
   119	 * hash is stored; the raw value exists solely inside the email that carries it.
   120	 */
   121	export async function requestPasswordReset(
   122	  input: PasswordResetRequestInput,
   123	): Promise<void> {
   124	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
   125	  if (!verdict.allowed) return;
   126	
   127	  const user = await userRepo.findUserByEmail(input.email);
   128	  if (!user) return;
   129	
   130	  const token = randomToken(32);
   131	  await resetTokenRepo.issueResetToken(
   132	    user.id,
   133	    hashToken(token),
   134	    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
   135	  );
   136	
   137	  const message = await renderEmail("password-reset", {
   138	    recipientName: user.name,
   139	    token,
   140	    expiresInMinutes: RESET_TTL_MS / 60_000,
   141	  });
   142	
   143	  await sendEmail({ to: user.email, ...message });
   144	}
   145	
   146	/**
   147	 * Consumes a reset token and rewrites the password hash. The token is marked
   148	 * used before the new hash is written, so a replay of the same link cannot
   149	 * overwrite a password the user has since changed again.
   150	 */
   151	export async function confirmPasswordReset(
   152	  input: PasswordResetConfirmInput,
   153	): Promise<User> {
   154	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
   155	  if (!verdict.allowed) {
   156	    throw new Error("Too many reset attempts; try again shortly");
   157	  }
   158	
   159	  const stored = await resetTokenRepo.findLiveResetToken(
   160	    hashToken(input.token),
   161	  );
   162	  if (!stored) throw new Error("That reset link is no longer valid");
   163	
   164	  await resetTokenRepo.consumeResetToken(stored.id);
   165	  await userRepo.updatePasswordHash(
   166	    stored.userId,
   167	    await hashPassword(input.password),
   168	  );
   169	
   170	  const user = await userRepo.findUserById(stored.userId);
   171	  if (!user) throw new Error("That reset link is no longer valid");
   172	
   173	  return user;
   174	}
