     1	/**
     2	 * Maps thrown domain errors onto `AppErrorShape`.
     3	 *
     4	 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
     5	 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
     6	 * `ZodError`); Server Actions and Route Handlers never propagate those to the
     7	 * client. Everything funnels through `toAppError()` so one thrown class maps
     8	 * to exactly one `ErrorCode` and one HTTP status, app-wide.
     9	 */
    10	import { FeatureDisabledError } from "@/lib/feature-flags";
    11	import { PermissionDeniedError } from "@/lib/permissions";
    12	import { InvalidSlugError } from "@/lib/slug";
    13	import { AlreadyArchivedError } from "@/lib/soft-delete";
    14	import { TenantScopeError } from "@/lib/tenant";
    15	import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
    16	import { ZodError, type ZodIssue } from "zod";
    17	
    18	export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
    19	  unauthorized: 401,
    20	  forbidden: 403,
    21	  not_found: 404,
    22	  validation_failed: 422,
    23	  conflict: 409,
    24	  rate_limited: 429,
    25	  plan_limit_exceeded: 402,
    26	  tenant_scope_violation: 403,
    27	  internal_error: 500,
    28	};
    29	
    30	/** True for the error classes this module knows how to translate faithfully. */
    31	export function isDomainError(error: unknown): boolean {
    32	  return (
    33	    error instanceof PermissionDeniedError ||
    34	    error instanceof TenantScopeError ||
    35	    error instanceof FeatureDisabledError ||
    36	    error instanceof AlreadyArchivedError ||
    37	    error instanceof InvalidSlugError ||
    38	    error instanceof ZodError
    39	  );
    40	}
    41	
    42	/** Collapses a `ZodError` into the `field → messages` map forms consume. */
    43	export function fieldErrorsFromZod(
    44	  error: ZodError,
    45	): Readonly<Record<string, readonly string[]>> {
    46	  const fields: Record<string, string[]> = {};
    47	  for (const issue of error.issues as readonly ZodIssue[]) {
    48	    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    49	    (fields[key] ??= []).push(issue.message);
    50	  }
    51	  return fields;
    52	}
